int minLcmSubset(const vector<long long>& a){
    int n=a.size(); map<long long,int> E; vector<map<long long,int>> f(n);
    for(int i=0;i<n;i++){ long long v=a[i];
        for(long long p=2;p*p<=v;p++) while(v%p==0){ f[i][p]++; v/=p; }
        if(v>1) f[i][v]++;
        for(auto [p,e]:f[i]) E[p]=max(E[p],e);
    }
    int k=0; map<long long,int> bit; for(auto [p,e]:E) bit[p]=k++;
    if(k==0) return 1;                       // LCM is 1
    set<int> masks;
    for(int i=0;i<n;i++){ int m=0;
        for(auto [p,e]:f[i]) if(e==E[p]) m|=1<<bit[p];
        if(m) masks.insert(m);
    }
    const int INF=1e9; vector<int> dp(1<<k,INF); dp[0]=0;
    for(int s=0;s<(1<<k);s++) if(dp[s]<INF)
        for(int m:masks) dp[s|m]=min(dp[s|m],dp[s]+1);
    return dp[(1<<k)-1];
}

