long long treasure(const vector<int>& A, const vector<long long>& B){
    int n=A.size(), LG=__lg(n)+1;
    vector<vector<long long>> sp(LG, B);
    for(int k=1;k<LG;k++) for(int i=0;i+(1<<k)<=n;i++)
        sp[k][i]=max(sp[k-1][i], sp[k-1][i+(1<<(k-1))]);
    auto qry=[&](int l,int r){ int k=__lg(r-l+1); return max(sp[k][l], sp[k][r-(1<<k)+1]); };
    int V=*max_element(A.begin(),A.end());
    vector<int> nxt(V+1, INT_MAX); long long tot=0;
    for(int i=n-1;i>=0;i--){
        int R=INT_MAX;
        for(int v=A[i]; v<=V; v+=A[i]) R=min(R, nxt[v]);
        if(R!=INT_MAX) tot+=qry(i,R);
        nxt[A[i]]=i;
    }
    return tot;
}

