vector<int> spiral(const vector<vector<int>>& a){
    vector<int> res; if(a.empty()) return res;
    int top=0, bot=a.size()-1, l=0, r=a[0].size()-1;
    while(top<=bot && l<=r){
        for(int j=l;j<=r;j++) res.push_back(a[top][j]); top++;
        for(int i=top;i<=bot;i++) res.push_back(a[i][r]); r--;
        if(top<=bot){ for(int j=r;j>=l;j--) res.push_back(a[bot][j]); bot--; }
        if(l<=r){ for(int i=bot;i>=top;i--) res.push_back(a[i][l]); l++; }
    }
    return res;
}

