    int m=g.size(), n=g[0].size(), z=0;
    for(auto& r:g) for(auto v:r) z+=(v==0);
    int nz=m*n-z;
    if(z<nz) return false;
    for(int i=0;i<m&&nz<=z;i++) for(int j=0;j<n&&nz<=z;j++) if(g[i][j]==0){
        long long rs=0, cs=0;
        for(int c=0;c<n;c++) rs+=g[i][c];
        for(int r=0;r<m;r++) cs+=g[r][j];
        g[i][j] = (rs<=cs) ? (rs%2==0 ? 2 : 1) : 3-rs%3;
        z--; nz++;
    }
    return true;
}

