    int x=st.top(); st.pop();
    reverseStack(st);
    insertAtBottom(st, x);
}

void bt(const vector<int>& a, vector<bool>& used, vector<int>& path, vector<vector<int>>& out){
    if(path.size()==a.size()){ out.push_back(path); return; }
    for(size_t i=0;i<a.size();i++){
        if(used[i]) continue;
        if(i>0 && a[i]==a[i-1] && !used[i-1]) continue;   // skip duplicates (a sorted)
        used[i]=true; path.push_back(a[i]);
        bt(a,used,path,out);
        path.pop_back(); used[i]=false;
    }
}

void permUnique(string& s, int i, vector<string>& out){
    if(i==(int)s.size()){ out.push_back(s); return; }
    set<char> tried;
    for(int j=i;j<(int)s.size();j++){
        if(tried.count(s[j])) continue;
        tried.insert(s[j]);
        swap(s[i],s[j]);
        permUnique(s,i+1,out);
        swap(s[i],s[j]);
    }
}

void gen(int n, int open, int close, string& cur, vector<string>& out){
    if((int)cur.size()==2*n){ out.push_back(cur); return; }
    if(open<n){ cur.push_back('('); gen(n,open+1,close,cur,out); cur.pop_back(); }
    if(close<open){ cur.push_back(')'); gen(n,open,close+1,cur,out); cur.pop_back(); }
}

int teamDivision(const vector<int>& a){   // values >= 0, n >= 2
    int n=a.size(), k=n/2, S=accumulate(a.begin(),a.end(),0);
    vector<vector<char>> dp(k+1, vector<char>(S+1,0));
    dp[0][0]=1;
    for(int x:a)
        for(int c=k;c>=1;c--)
            for(int s=S;s>=x;s--)
                if(dp[c-1][s-x]) dp[c][s]=1;
    int best=INT_MAX;
    for(int s=0;s<=S;s++) if(dp[k][s]) best=min(best, abs(S-2*s));
    return best;
}

