        if(!dp[i-1][s]){ res.push_back(a[i-1]); s-=a[i-1]; }
    return res;
}

void comb(const vector<int>& c, int start, int rem, vector<int>& path, vector<vector<int>>& out){
    if(rem==0){ out.push_back(path); return; }
    for(int i=start;i<(int)c.size() && c[i]<=rem;i++){   // c sorted
        path.push_back(c[i]);
        comb(c, i, rem-c[i], path, out);                 // i: reuse allowed
        path.pop_back();
    }
}

