int R[9], C[9], B[9]; vector<pair<int,int>> emp;
bool rec(vector<vector<char>>& g, size_t k){
    if(k==emp.size()) return true;
    auto [r,c]=emp[k]; int b=(r/3)*3+c/3;
    for(int d=1;d<=9;d++){
        int bit=1<<d;
        if((R[r]|C[c]|B[b])&bit) continue;
        R[r]|=bit; C[c]|=bit; B[b]|=bit; g[r][c]='0'+d;
        if(rec(g,k+1)) return true;
        R[r]^=bit; C[c]^=bit; B[b]^=bit; g[r][c]='.';
    }
    return false;
}
bool solveSudoku(vector<vector<char>>& g){
    memset(R,0,sizeof R); memset(C,0,sizeof C); memset(B,0,sizeof B); emp.clear();
    for(int r=0;r<9;r++) for(int c=0;c<9;c++){
        if(g[r][c]=='.') emp.push_back({r,c});
        else { int bit=1<<(g[r][c]-'0'); R[r]|=bit; C[c]|=bit; B[(r/3)*3+c/3]|=bit; }
    }
    return rec(g,0);
}

int smartCost(const array<int,9>& in){
    static vector<array<int,9>> valid;
    if(valid.empty()){
        array<int,9> p; iota(p.begin(),p.end(),1);
        do{
            bool ok=true;
            for(int i=0;i<3;i++){
                if((p[3*i]+p[3*i+1]+p[3*i+2])%5) ok=false;
                if((p[i]+p[i+3]+p[i+6])%5) ok=false;
            }
            if((p[0]+p[4]+p[8])%5 || (p[2]+p[4]+p[6])%5) ok=false;
            if(ok) valid.push_back(p);
        } while(next_permutation(p.begin(),p.end()));
    }
    int best=INT_MAX;
    for(auto& v:valid){ int c=0; for(int i=0;i<9;i++) c+=abs(in[i]-v[i]); best=min(best,c); }
    return best;
}

