vector<int> prefixMinDistinct(vector<long long> A, const vector<pair<int,long long>>& qs){
    map<int,long long> rec;                 // positions that are strict prefix minima
    long long cur=LLONG_MAX;
    for(int i=0;i<(int)A.size();i++) if(A[i]<cur){ cur=A[i]; rec[i]=A[i]; }
    vector<int> ans;
    for(auto [x,y]:qs){
        int p=x-1; A[p]-=y; long long v=A[p];
        auto it=rec.lower_bound(p);
        long long prevMin = (it==rec.begin()) ? LLONG_MAX : prev(it)->second;
        if(v<prevMin){
            rec[p]=v;
            it=rec.upper_bound(p);
