long long minInvReverse(const vector<int>& p, int K){      // p is a permutation of 1..n
    int n=p.size(); long long total=0;
    BIT b(n);
    for(int i=0;i<n;i++){ total+=i-b.q(p[i]); b.add(p[i],1); }
    BIT w(n); long long inv=0;
    for(int i=0;i<K;i++){ inv+=i-w.q(p[i]); w.add(p[i],1); }
    long long best=inv;
    for(int l=1;l+K<=n;l++){
        inv-=w.q(p[l-1]-1); w.add(p[l-1],-1);              // drop leftmost
        int x=p[l+K-1]; inv+=(K-1)-w.q(x); w.add(x,1);     // add new rightmost
        best=max(best,inv);
    }
    long long kk=1LL*K*(K-1)/2;
    return min(total, total+kk-2*best);                    // 'at most one' reversal
}

