}

long long countPairs(const vector<int>& A){
    const long long MOD=1e9+7; int n=A.size(), OFF=n+1, SZ=3*n+5;
    vector<long long> X(n), Y(n);
    map<int,int> f; for(int i=0;i<n;i++){ int fi=++f[A[i]]; X[i]=fi-(long long)f.size()/2; }
    map<int,int> g; for(int j=n-1;j>=0;j--){ int gj=++g[A[j]]; Y[j]=(long long)g.size()/2-gj; }
    vector<int> bit(SZ+1,0);
    auto add=[&](int i){ for(i+=OFF;i<=SZ;i+=i&-i) bit[i]++; };
    auto cnt=[&](long long v){ long long s=0; int i=min<long long>(v+OFF,SZ); for(;i>0;i-=i&-i) s+=bit[i]; return s; };
    long long ans=0;
    for(int j=1;j<n;j++){ add(X[j-1]); ans+=cnt(Y[j]); }   // #i<j with X_i <= Y_j
    return ans%MOD;
}
